const fs = require('node:fs');
const path = require('node:path');
const { fetchTranslations } = require('./fetchTranslations');
const {
  processTranslations,
  saveFullResponse,
  saveTranslationsAsJson,
} = require('./processTranslations');
const { resolveTargetEnvironment, shouldUseDraftValues } = require('./resolveTargetEnvironment');
const { APPLANGA_TAG } = require('./extractEntries');
const { resolveRequestedTagIds, resolveRequestedTagIdsBreakdown } = require('./resolveRequestedTagIds');

const CONFIG_BASENAME = 'translation.config.js';

function isPathWithinDirectory(targetPath, directoryPath) {
  const relativePath = path.relative(directoryPath, targetPath);
  return relativePath === '' || (!relativePath.startsWith('..') && !path.isAbsolute(relativePath));
}

function resolveConfigPath(configPath) {
  if (!configPath || typeof configPath !== 'string') {
    throw new Error('Config path is required');
  }

  const cwd = fs.realpathSync(process.cwd());
  const resolvedPath = path.resolve(cwd, configPath);

  if (path.basename(resolvedPath) !== CONFIG_BASENAME) {
    throw new Error(`Config file must be named ${CONFIG_BASENAME}`);
  }

  if (path.extname(resolvedPath) !== '.js') {
    throw new Error('Config file must be a .js file');
  }

  if (!fs.existsSync(resolvedPath)) {
    throw new Error(`Config file not found: ${configPath}`);
  }

  const realConfigPath = fs.realpathSync(resolvedPath);

  if (!isPathWithinDirectory(realConfigPath, cwd)) {
    throw new Error('Config path must be within the current working directory');
  }

  if (!fs.statSync(realConfigPath).isFile()) {
    throw new Error('Config path must point to a file');
  }

  return realConfigPath;
}

function loadConfig(configPath) {
  const resolvedPath = resolveConfigPath(configPath);
  // eslint-disable-next-line import/no-dynamic-require, global-require
  return require(resolvedPath);
}

function loadDotenv(configPath) {
  try {
    const dotenv = require('dotenv');
    const configDir = path.dirname(path.resolve(process.cwd(), configPath));
    dotenv.config({ path: path.resolve(configDir, '../../.env') });
    dotenv.config({ path: path.resolve(process.cwd(), '.env') });
  } catch (error) {
    // dotenv is optional for CI environments
  }
}

async function generateTranslations(configPath) {
  const resolvedConfigPath = resolveConfigPath(configPath);

  loadDotenv(resolvedConfigPath);
  const config = loadConfig(resolvedConfigPath);

  const bearerToken = config.bearerToken || process.env.APPLANGA_API_KEY || '';
  const targetEnvironment = resolveTargetEnvironment();
  const useDraftValues = shouldUseDraftValues(targetEnvironment);

  console.log('🚀 Starting translation files generation...\n');

  if (!bearerToken || bearerToken === 'your_applanga_api_key_here') {
    console.warn('⚠️  APPLANGA_API_KEY not set or using placeholder value');
    console.log('ℹ️  Translation generation is skipped locally (handled by pipeline)');
    console.log('ℹ️  To generate translations locally, set APPLANGA_API_KEY in your .env file\n');
    return { skipped: true };
  }

  if (!config.requestedTagIds) {
    throw new Error('config.requestedTagIds is required in translation.config.js');
  }

  const configWithToken = { ...config, bearerToken };
  const outputDir = path.resolve(path.dirname(resolvedConfigPath), config.outputPath);

  const { mfeTagIds, additionalTagIds, mergedTagIds } = resolveRequestedTagIdsBreakdown(config);

  console.log(`📌 Tag branches: all response branches with entries (e.g. "${APPLANGA_TAG}")`);
  console.log(`📌 MFE tag ID(s): ${JSON.stringify(mfeTagIds)}`);
  console.log(`📌 Shared-components tag ID(s): ${JSON.stringify(additionalTagIds)}`);
  console.log(`📌 Tag ID(s) sent to Applanga API: ${JSON.stringify(mergedTagIds)}`);
  console.log(
    `📌 Value mode: ${useDraftValues ? 'draft (local/SIT: prefer .d)' : 'release (UAT/PROD: prefer .v)'}`
  );
  console.log(`📁 Output path: ${outputDir}\n`);

  const apiResponse = await fetchTranslations(configWithToken);
  console.log('✅ Translations received from API\n');

  saveFullResponse(apiResponse, outputDir);

  const translations = processTranslations(apiResponse);
  const languages = Object.keys(translations);

  if (languages.length === 0) {
    throw new Error('No translations found in API response');
  }

  console.log(`📝 Processing ${languages.length} language(s): ${languages.join(', ')}\n`);

  let processedCount = 0;
  languages.forEach((langCode) => {
    const filePath = saveTranslationsAsJson(
      langCode,
      translations[langCode],
      outputDir,
      useDraftValues
    );
    if (filePath) {
      processedCount += 1;
    }
  });

  if (processedCount === 0) {
    throw new Error('No translation files generated. Check that the API response contains translation entries.');
  }

  console.log(`\n🎉 Successfully generated ${processedCount} translation file(s)!`);
  return { skipped: false, processedCount };
}

function parseArgs(argv) {
  const command = argv[0];

  if (command !== 'generate') {
    return { command: command || null };
  }

  const configFlagIndex = argv.indexOf('--config');
  if (configFlagIndex === -1 || !argv[configFlagIndex + 1]) {
    return { command, configPath: null };
  }

  return {
    command,
    configPath: argv[configFlagIndex + 1],
  };
}

async function runCli(argv) {
  const { command, configPath } = parseArgs(argv);

  if (command !== 'generate') {
    console.log('Usage: bees-mfe-translations generate --config <path-to-translation.config.js>');
    process.exit(command ? 1 : 0);
  }

  if (!configPath) {
    console.error('❌ Error: --config is required');
    console.log('Usage: bees-mfe-translations generate --config <path-to-translation.config.js>');
    process.exit(1);
  }

  try {
    const result = await generateTranslations(configPath);
    process.exit(result.skipped ? 0 : 0);
  } catch (error) {
    console.error('\n❌ Error:', error.message);
    process.exit(1);
  }
}

module.exports = {
  generateTranslations,
  parseArgs,
  resolveConfigPath,
  runCli,
};
